import{_ as l,o as i,c as a,a5 as o}from"./chunks/framework.Bt0SrEfo.js";const b=JSON.parse('{"title":"安全检查清单(部署前必看)","description":"","frontmatter":{},"headers":[],"relativePath":"security/5-checklist.md","filePath":"security/5-checklist.md","lastUpdated":1790177750000}'),t={name:"security/5-checklist.md"};function r(c,e,n,s,d,h){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="安全检查清单-部署前必看" tabindex="-1">安全检查清单(部署前必看) <a class="header-anchor" href="#安全检查清单-部署前必看" aria-label="Permalink to &quot;安全检查清单(部署前必看)&quot;">​</a></h1><blockquote><p>复制到 PR 模板 / 上线评审 Checklist,逐项打勾。</p></blockquote><h2 id="一、输入与渲染" tabindex="-1">一、输入与渲染 <a class="header-anchor" href="#一、输入与渲染" aria-label="Permalink to &quot;一、输入与渲染&quot;">​</a></h2><ul><li>[ ] 所有用户输入走统一过滤层,<strong>不直接拼接到 DOM / SQL / shell</strong></li><li>[ ] 富文本(评论、商品描述、私信)走 <strong>DOMPurify 白名单</strong></li><li>[ ] URL 跳转校验 protocol(只允许 http/https)</li><li>[ ] 文件上传校验 MIME 类型 + 扩展名 + 实际内容(防伪装)</li><li>[ ] JSON 输出避免泄漏堆栈 / 内部错误信息</li></ul><h2 id="二、cookie-与会话" tabindex="-1">二、Cookie 与会话 <a class="header-anchor" href="#二、cookie-与会话" aria-label="Permalink to &quot;二、Cookie 与会话&quot;">​</a></h2><ul><li>[ ] 敏感 Cookie 设 <code>HttpOnly</code>(防 JS 窃取)</li><li>[ ] 强制 HTTPS 的 Cookie 加 <code>Secure</code></li><li>[ ] 跨站请求防护加 <code>SameSite=Lax</code> 或 <code>Strict</code></li><li>[ ] Session ID 用 <code>__Host-</code> 前缀(防子域劫持)</li><li>[ ] 登录态过期时间合理(token 15~30 分钟,refresh 7~30 天)</li></ul><h2 id="三、csp-content-security-policy" tabindex="-1">三、CSP(Content Security Policy) <a class="header-anchor" href="#三、csp-content-security-policy" aria-label="Permalink to &quot;三、CSP(Content Security Policy)&quot;">​</a></h2><ul><li>[ ] 至少开 <code>Content-Security-Policy-Report-Only</code> 观察违规</li><li>[ ] <code>default-src &#39;self&#39;</code> 起步</li><li>[ ] inline script 用 <strong>nonce</strong> 机制,不要 <code>unsafe-inline</code></li><li>[ ] <code>frame-ancestors &#39;none&#39;</code> 防点击劫持</li><li>[ ] <code>base-uri &#39;self&#39;</code> 防 <code>&lt;base&gt;</code> 劫持</li><li>[ ] 上线前切换为强制 + 收集违规报告</li></ul><h2 id="四、csrf-与跨域" tabindex="-1">四、CSRF 与跨域 <a class="header-anchor" href="#四、csrf-与跨域" aria-label="Permalink to &quot;四、CSRF 与跨域&quot;">​</a></h2><ul><li>[ ] 关键接口(支付、修改密码)要求 <strong>CSRF Token</strong></li><li>[ ] 浏览器级别防护:Cookie 用 SameSite</li><li>[ ] CORS <strong>不允许 <code>*</code></strong>,配置白名单</li><li>[ ] 关键操作二次验证(密码 / 短信 / 邮箱)</li><li>[ ] 服务端做权限校验,<strong>不依赖前端按钮 disabled</strong></li></ul><h2 id="五、iframe-安全" tabindex="-1">五、iframe 安全 <a class="header-anchor" href="#五、iframe-安全" aria-label="Permalink to &quot;五、iframe 安全&quot;">​</a></h2><ul><li>[ ] 自家页面加 <code>X-Frame-Options: DENY</code> 或 CSP <code>frame-ancestors &#39;none&#39;</code></li><li>[ ] 嵌入第三方 iframe 默认 <code>sandbox=&quot;&quot;</code>(最严格)</li><li>[ ] 父页通过 <code>postMessage</code> 通信,严格校验 <code>origin</code> + <code>source</code></li><li>[ ] <code>targetOrigin</code> 不传 <code>&#39;*&#39;</code></li></ul><h2 id="六、第三方依赖" tabindex="-1">六、第三方依赖 <a class="header-anchor" href="#六、第三方依赖" aria-label="Permalink to &quot;六、第三方依赖&quot;">​</a></h2><ul><li>[ ] <code>npm audit</code> 无高危漏洞</li><li>[ ] <code>package-lock.json</code> 进入仓库</li><li>[ ] CI 集成 Snyk / Dependabot</li><li>[ ] 关键依赖固定精确版本(不写 <code>^</code>)</li><li>[ ] 私有 npm 包走内网仓库</li></ul><h2 id="七、网络与传输" tabindex="-1">七、网络与传输 <a class="header-anchor" href="#七、网络与传输" aria-label="Permalink to &quot;七、网络与传输&quot;">​</a></h2><ul><li>[ ] 全站强制 HTTPS(301 重定向 + HSTS)</li><li>[ ] HSTS preload(浏览器内置)</li><li>[ ] 不忽略证书警告(用户侧)</li><li>[ ] 敏感接口单独加密(国密 / RSA)</li><li>[ ] WebSocket 用 TLS(wss://)</li></ul><h2 id="八、监控与响应" tabindex="-1">八、监控与响应 <a class="header-anchor" href="#八、监控与响应" aria-label="Permalink to &quot;八、监控与响应&quot;">​</a></h2><ul><li>[ ] 错误监控(Sentry / 自建)</li><li>[ ] 安全事件告警(异常登录、暴力破解、敏感操作)</li><li>[ ] 操作日志(谁、何时、做了什么)留 6 个月以上</li><li>[ ] 应急响应流程文档化</li><li>[ ] 关键资产清单 + 应急预案</li></ul><h2 id="九、认证与授权" tabindex="-1">九、认证与授权 <a class="header-anchor" href="#九、认证与授权" aria-label="Permalink to &quot;九、认证与授权&quot;">​</a></h2><ul><li>[ ] 密码哈希用 <strong>bcrypt / argon2</strong>(不用 MD5/SHA1)</li><li>[ ] 多因素认证(管理员 / 财务角色强制)</li><li>[ ] 失败登录限速(防暴力破解)</li><li>[ ] 密码强度校验(8 位 + 复杂度)</li><li>[ ] 服务端独立校验权限,<strong>不只信前端</strong></li></ul><h2 id="十、业务场景专项" tabindex="-1">十、业务场景专项 <a class="header-anchor" href="#十、业务场景专项" aria-label="Permalink to &quot;十、业务场景专项&quot;">​</a></h2><h3 id="支付-转账" tabindex="-1">支付 / 转账 <a class="header-anchor" href="#支付-转账" aria-label="Permalink to &quot;支付 / 转账&quot;">​</a></h3><ul><li>[ ] 操作前确认弹窗(显示金额、收款方)</li><li>[ ] 二次密码 / 短信验证</li><li>[ ] 限速(同一账户每小时最多 5 笔)</li><li>[ ] 风控引擎实时检测异常</li></ul><h3 id="富文本-评论" tabindex="-1">富文本 / 评论 <a class="header-anchor" href="#富文本-评论" aria-label="Permalink to &quot;富文本 / 评论&quot;">​</a></h3><ul><li>[ ] DOMPurify 白名单</li><li>[ ] 长度限制(评论 1000 字以内)</li><li>[ ] 关键词过滤(广告、敏感词)</li><li>[ ] XSS 检测后端兜底</li></ul><h3 id="第三方登录" tabindex="-1">第三方登录 <a class="header-anchor" href="#第三方登录" aria-label="Permalink to &quot;第三方登录&quot;">​</a></h3><ul><li>[ ] OAuth state 参数防 CSRF</li><li>[ ] postMessage 校验 origin</li><li>[ ] 回调地址白名单</li><li>[ ] 不通过 popup 直接传 token,走后端换 code</li></ul><h2 id="十一、按项目阶段使用" tabindex="-1">十一、按项目阶段使用 <a class="header-anchor" href="#十一、按项目阶段使用" aria-label="Permalink to &quot;十一、按项目阶段使用&quot;">​</a></h2><h3 id="新项目开发期" tabindex="-1">新项目开发期 <a class="header-anchor" href="#新项目开发期" aria-label="Permalink to &quot;新项目开发期&quot;">​</a></h3><ul><li>[ ] 选好框架默认安全策略(Next.js 默认 CSP、Svelte 安全头)</li><li>[ ] 引入 lint 规则(eslint-plugin-security)</li><li>[ ] CI 集成 SAST(代码扫描)</li><li>[ ] 关键依赖审计(首次安装时跑一遍)</li></ul><h3 id="上线前" tabindex="-1">上线前 <a class="header-anchor" href="#上线前" aria-label="Permalink to &quot;上线前&quot;">​</a></h3><ul><li>[ ] 跑一遍完整 Checklist</li><li>[ ] 渗透测试(关键业务)</li><li>[ ] 应急响应演练</li><li>[ ] 备份可用性验证</li></ul><h3 id="运营期" tabindex="-1">运营期 <a class="header-anchor" href="#运营期" aria-label="Permalink to &quot;运营期&quot;">​</a></h3><ul><li>[ ] 周:依赖审计(<code>npm audit</code>)、监控告警检查</li><li>[ ] 月:CSP 违规报告审视、权限审计</li><li>[ ] 季:渗透测试、应急演练、密钥轮换</li></ul><h2 id="十二、参考资料" tabindex="-1">十二、参考资料 <a class="header-anchor" href="#十二、参考资料" aria-label="Permalink to &quot;十二、参考资料&quot;">​</a></h2><ul><li><a href="https://cheatsheetseries.owasp.org/" target="_blank" rel="noreferrer">OWASP Cheat Sheet Series</a></li><li><a href="https://infosec.mozilla.org/guidelines/web_security" target="_blank" rel="noreferrer">Mozilla Web Security Guidelines</a></li><li>《白帽子讲 Web 安全》(吴翰清)</li></ul>',36)])])}const S=l(t,[["render",r]]);export{b as __pageData,S as default};
